<?php
declare(strict_types=1);
namespace App\Support\Notifications;
use App\Models\Meeting; use App\Models\User;
final class MeetingCancellationSnapshot { public static function fromMeeting(Meeting $m,User $actor):array{$m->loadMissing(['coach','student']);return ['meeting_id'=>(string)$m->id,'scheduled_at'=>$m->scheduled_at?->toISOString(),'coach_id'=>(string)$m->coach_id,'coach_name'=>$m->coach?->name,'student_id'=>(string)$m->student_id,'student_name'=>$m->student?->name,'canceled_by_user_id'=>(string)$actor->id,'canceled_by_name'=>$actor->name];} public static function toMeeting(array $s):Meeting{$m=new Meeting; $m->exists=true;$m->setRawAttributes(['id'=>$s['meeting_id'],'scheduled_at'=>$s['scheduled_at'],'coach_id'=>$s['coach_id'],'student_id'=>$s['student_id'],'canceled_by_user_id'=>$s['canceled_by_user_id'],'status'=>'canceled']);$m->setRelation('coach',(new User)->newInstance(['id'=>$s['coach_id'],'name'=>$s['coach_name']]));$m->setRelation('student',(new User)->newInstance(['id'=>$s['student_id'],'name'=>$s['student_name']]));$m->setRelation('canceledBy',(new User)->newInstance(['id'=>$s['canceled_by_user_id'],'name'=>$s['canceled_by_name']]));return $m;}}
